{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "The passage leaves repeated testing unspecified."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 are reinterpreted as repeated evaluation of an unchanged AI system under fixed conditions. Repeatability evidence is insufficient: 0 means insufficient information, not demonstrated inadequacy. Human test-taker characteristics and debriefing are inapplicable to the assessed system."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly excludes repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "No repeated scores support stability; this does not demonstrate instability."
        }
      ],
      "instrument_review": "Under EFPA 9.3 and 9.7, reinterpreted for AI run consistency, the evaluation supplies no repeatability evidence. A 0 for this evidence reflects insufficient information about precision, despite explicit knowledge that repetition was not conducted. Human test-taker requirements are inapplicable."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations explicitly held the listed conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability definition of at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 accommodates the observed score range as alternative precision evidence; 9.3 is reinterpreted as AI repeatability. This supports the stated local stability criterion, without establishing reliability across systems, alternate puzzles, or conditions. EFPA coefficient thresholds cannot be applied directly to a score range. Human test-taker requirements are inapplicable."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The passage explicitly describes repeated testing under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability limit of two percentage points."
        }
      ],
      "instrument_review": "Under EFPA 9.7, reinterpreted for AI run precision, the supplied results demonstrate failure of the stated stability criterion rather than missing evidence. Section 9.8 requires judging precision against the intended comparison use; these fluctuations undermine dependable comparisons. Human test-taker requirements are inapplicable."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance does not establish repeated evaluation."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "No repeated-score findings support stability."
        }
      ],
      "instrument_review": "Installation instructions are relevant to EFPA 6.3.8 software guidance, but do not supply evidence for 9.3 or 9.7, reinterpreted as AI repeatability. Precision evidence remains insufficient, corresponding to 0 rather than demonstrated inadequacy. Human test-taker requirements are inapplicable."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported exact-grid results show better observed performance by A on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The passage supplies no evidence establishing a cross-domain intelligence difference."
        }
      ],
      "instrument_review": "EFPA 3.2 describes the observed scores; 10.1 and 10.5 distinguish their narrow interpretation from broader construct claims. The intended use matches the evaluated puzzle domain, but repeatability and broader validity remain unestablished. Section 8.3.2.2 permits a norms exception for an explicitly ranking-only purpose. Human population norms are not automatically AI reference norms; human test-taker requirements are inapplicable."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the higher observed score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence for general intelligence across domains."
        }
      ],
      "instrument_review": "EFPA 6.1.1, 10.1, 10.3, and 10.5 require evidence supporting the intended cross-domain interpretation, here reinterpreted as an AI capability claim. Narrow grid results leave that interpretation unsupported; insufficient validity evidence is distinct from proof that the claim is false. Under EFPA's critical-quality guidance, a critical validity rating of 0 restricts the intended use to research or exceptional expert circumstances. Human test-taker requirements are inapplicable."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Test scores alone provide no supplied evidence of improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports higher correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings do not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 recognizes experimental evidence; 10.3.2 and 10.5 address its relevance to the intended outcome. Random allocation, preregistration, blinded correctness checking, and the reported uncertainty support the workshop-specific assistance choice. The 120 inspectors are trial participants, not 120 evaluated AI systems; human sample-size anchors cannot automatically rate AI measurement precision. Human testing questions apply only where relevant to these inspectors. Criterion reliability, benchmark-score linkage, wider generalization, and safety benefits remain unestablished."
    }
  ],
  "closing_note": "The request for brief case reviews resolves the apparent tension with applying the complete EFPA model: relevant original sections were used without replacing the instrument or completing full forms. Probe labels are statement classifications, not EFPA ratings. No aggregate quality score was calculated. Reviews use only the supplied passages; missing evidence does not establish poor quality or a false underlying claim. EFPA 2025, version 5.0, is supplied under CC BY-SA 4.0, source https://www.efpa.eu/; these reviews imply no EFPA endorsement. No substantive instruction remains unclear."
}
